/* Cartão do criador igual em celular, tablet e computador. */
.rodape-criador {
  width: 100%;
  height: 66px;
  min-height: 0;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  border: 1px solid rgba(183, 141, 69, .34);
