/* Rótulo reduzido da página de história no menu. */
.menu-lista a[href="historia.html"] .menu-mobile-texto > strong {
  position: relative;
  display: inline-block;
  width: 7.6ch;
  overflow: hidden;
  color: transparent !important;
  white-space: nowrap;
}

.menu-lista a[href="historia.html"] .menu-mobile-texto > strong::after {
  content: "História";
  position: absolute;
  inset: 0 auto 0 0;
  color: #e7d3aa;
  white-space: nowrap;
}

.menu-lista a[href="historia.html"].ativo .menu-mobile-texto > strong::after,
.menu-lista a[href="historia.html"]:hover .menu-mobile-texto > strong::after,
.menu-lista a[href="historia.html"]:focus-visible .menu-mobile-texto > strong::after {
  color: #fff0c8;
}

.menu-lista a[href="historia.html"]:not(:has(.menu-mobile-texto)) {
  position: relative;
  font-size: 0;
}

.menu-lista a[href="historia.html"]:not(:has(.menu-mobile-texto))::after {
  content: "História";
  color: #e7d3aa;
  font-size: 1rem;
}

/* O rótulo é atualizado no HTML; não usar largura fixa nem texto sobreposto. */
.menu-lista a[href="historia.html"] .menu-mobile-texto > strong {
  width: auto !important;
  overflow: visible !important;
  color: inherit !important;
}

.menu-lista a[href="historia.html"] .menu-mobile-texto > strong::after,
.menu-lista a[href="historia.html"]:not(:has(.menu-mobile-texto))::after {
  display: none !important;
}

.menu-lista a[href="historia.html"]:not(:has(.menu-mobile-texto)) {
  font-size: inherit;
}

/* Navegação exclusiva das páginas de estudo. */
.menu-lista.menu-estudo-lista > li:not(.menu-estudo-link) {
  display: none !important;
}

.menu-lista.menu-estudo-lista {
  justify-content: flex-end;
}

