:root:has(:where(body.pagina-inicial)){
  --verde: #1f5b3a;
  --verde-escuro: #123c29;
  --verde-claro: #dce8d8;
  --vermelho: #9e2f2f;
  --vermelho-escuro: #6f2020;
  --amarelo: #d5a824;
  --amarelo-claro: #f0d98a;
  --papel: #f4eedf;
  --papel-claro: #fffaf0;
  --tinta: #26231d;
  --tinta-suave: #696257;
  --branco: #ffffff;
  --linha: rgba(38, 35, 29, 0.14);
  --sombra: 0 18px 50px rgba(32, 28, 20, 0.14);
  --raio: 22px;
  --largura: 1180px;
}

html:has(:where(body.pagina-inicial)), :where(body.pagina-inicial), :where(body.pagina-inicial) *{
