}

:where(body.pagina-inicial) img,
:where(body.pagina-inicial) svg{
  max-width: 100%;
}

:where(body.pagina-inicial) button,
:where(body.pagina-inicial) input{
  font: inherit;
}

:where(body.pagina-inicial) button{
  cursor: pointer;
}

:where(body.pagina-inicial) .container{
