    repeating-linear-gradient(0deg, rgba(76, 49, 25, 0.045) 0 1px, transparent 1px 6px),
    #d8bd8e;
}

body:where(.pagina-calendario)::before{
  content: "";
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  opacity: 0.16;
  background:
    repeating-radial-gradient(circle at 20% 30%, rgba(44, 27, 14, 0.28) 0 0.5px, transparent 0.5px 4px),
