}

/* Mantém todos os conteúdos flex/grid autorizados a encolher */
:where(body.pagina-calendario) .container,
:where(body.pagina-calendario) .header-inner,
:where(body.pagina-calendario) .logo,
:where(body.pagina-calendario) .logo-texto,
:where(body.pagina-calendario) .hero-conteudo,
:where(body.pagina-calendario) .hero-texto,
:where(body.pagina-calendario) .hero-acoes{
