   ========================================================== */
:root:has(:where(body.estilo-guia-concorrente)){
  --verde: #354a32;
  --verde-escuro: #1f3022;
  --verde-claro: #c8c6a4;
  --vermelho: #71392f;
  --vermelho-escuro: #4d281f;
  --amarelo: #bd9347;
  --amarelo-claro: #e0c47a;
  --papel: #dfc99f;
  --papel-claro: #f0dfba;
  --tinta: #302117;
  --tinta-suave: #65503b;
  --branco: #fff7e3;
  --linha: rgba(60, 40, 23, 0.28);
  --sombra: 0 16px 35px rgba(41, 25, 14, 0.24);
  --raio: 6px;
}

body:where(.estilo-guia-concorrente){
  position: relative;
  color: var(--tinta);
  background:
    radial-gradient(circle at 16% 10%, rgba(255, 247, 220, 0.48), transparent 30%),
