    #d8bd8e;
}

body:where(.estilo-guia-concorrente)::before{
  content: "";
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  opacity: 0.16;
  background:
    repeating-radial-gradient(circle at 20% 30%, rgba(44, 27, 14, 0.28) 0 0.5px, transparent 0.5px 4px),
    repeating-linear-gradient(90deg, transparent 0 19px, rgba(64, 40, 20, 0.055) 20px 21px);
