/* Identidade com o laçador */
:where(body.estilo-guia-concorrente) .logo-lacador-frame{
  width: 62px;
  height: 68px;
  flex: 0 0 62px;
  position: relative;
  display: grid;
  place-items: end center;
  overflow: hidden;
  border: 3px double #d0ae65;
  border-radius: 8px 8px 17px 17px;
  background:
    linear-gradient(rgba(24, 43, 29, .94), rgba(24, 43, 29, .94)),
    repeating-linear-gradient(90deg, #382518 0 8px, #432c1d 8px 16px);
  box-shadow:
    inset 0 0 0 4px #39251a,
    5px 6px 0 rgba(0, 0, 0, .25);
  transform: rotate(-2deg);
}

:where(body.estilo-guia-concorrente) .logo-lacador-frame::before{
  content: "";
  position: absolute;
  inset: 5px;
  z-index: 0;
  border: 1px solid rgba(236, 207, 139, .44);
  border-radius: 4px 4px 12px 12px;
}

:where(body.estilo-guia-concorrente) .logo-lacador-frame::after{
  content: "";
  position: absolute;
  left: 7px;
  right: 7px;
  bottom: 5px;
  height: 9px;
  z-index: 1;
  border-radius: 50%;
  background: rgba(47, 30, 19, .82);
  filter: blur(2px);
}

:where(body.estilo-guia-concorrente) .logo-lacador-img{
  width: auto;
  height: 62px;
  position: relative;
  z-index: 2;
  object-fit: contain;
  transform: translateY(5px);
  filter:
    drop-shadow(1px 2px 0 rgba(239, 213, 159, .25))
    drop-shadow(2px 3px 2px rgba(0, 0, 0, .48));
}

:where(body.estilo-guia-concorrente) .hero-lacador{
  min-height: 510px;
  position: relative;
  display: grid;
  place-items: center;
  isolation: isolate;
}

:where(body.estilo-guia-concorrente) .moldura-lacador{
  width: min(92%, 430px);
  aspect-ratio: 4 / 5;
  position: relative;
  overflow: hidden;
  border: 5px double #d1ae64;
  border-radius: 48% 48% 18px 18px / 28% 28% 18px 18px;
  background:
    radial-gradient(circle at 72% 21%, rgba(225, 190, 105, .34) 0 9%, transparent 9.6%),
    linear-gradient(180deg, #263b29 0 61%, #9d783c 61% 63%, #5a3821 63% 100%);
  box-shadow:
    0 25px 46px rgba(0, 0, 0, .42),
    inset 0 0 0 8px #2f2015,
    inset 0 0 0 11px #b88f48;
}

:where(body.estilo-guia-concorrente) .moldura-lacador::before{
  content: "";
  position: absolute;
  inset: 18px;
  z-index: 1;
  pointer-events: none;
  border: 2px solid rgba(232, 203, 137, .46);
  border-radius: 46% 46% 10px 10px / 27% 27% 10px 10px;
}

:where(body.estilo-guia-concorrente) .moldura-lacador::after{
  content: "";
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: .19;
  background:
    repeating-linear-gradient(90deg, transparent 0 19px, rgba(255, 244, 209, .11) 20px 21px),
    linear-gradient(138deg, transparent 0 42%, rgba(242, 213, 141, .22) 42.4% 43.1%, transparent 43.5%);
  mix-blend-mode: screen;
}

