    flex: 1 1 auto !important;
    gap: 8px !important; /* EDITAR AQUI: distância entre símbolo e nome */
  }

  /* Símbolo um pouco mais compacto para sobrar espaço para o nome */
  :where(body.estilo-guia-concorrente) .logo-lacador-frame{
    width: 50px !important;
    height: 62px !important;
    flex: 0 0 50px !important;
  }

