:where(body.pagina-prova-campeira) .campeira-nova-hero{
  background:
    linear-gradient(90deg, rgba(27, 47, 31, .97), rgba(24, 39, 27, .91)),
    repeating-linear-gradient(90deg, #304532 0 24px, #293d2c 24px 48px);
}

:where(body.pagina-prova-campeira) .campeira-hero-grid{
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 50px;
  align-items: center;
}

:where(body.pagina-prova-campeira) .campeira-hero-selo{
  aspect-ratio: 1;
  display: grid;
  place-content: center;
  justify-items: center;
  padding: 24px;
  border: 4px double #c39a4b;
  border-radius: 50%;
  color: #f4e4bd;
  background:
    radial-gradient(circle, rgba(106, 57, 46, .97) 0 58%, rgba(42, 29, 20, .98) 59%);
  box-shadow:
    13px 16px 0 rgba(0, 0, 0, .24),
    inset 0 0 0 9px rgba(223, 190, 113, .08);
  text-align: center;
  transform: rotate(2deg);
}

:where(body.pagina-prova-campeira) .campeira-hero-selo span{
  font-family: Georgia, "Times New Roman", serif;
  font-size: 5.2rem;
  font-weight: 900;
  line-height: .85;
  color: #d7b361;
}

:where(body.pagina-prova-campeira) .campeira-hero-selo strong{
  margin-top: 11px;
  font-size: .92rem;
  letter-spacing: .1em;
  text-transform: uppercase;
}

:where(body.pagina-prova-campeira) .campeira-hero-selo small{
  max-width: 155px;
  margin-top: 9px;
  color: #d7c29a;
  font-size: .67rem;
  letter-spacing: .08em;
  text-transform: uppercase;
}

:where(body.pagina-prova-campeira) .campeira-saberes{
  background:
    linear-gradient(rgba(230, 211, 171, .96), rgba(230, 211, 171, .96)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(77, 49, 25, .045) 9px 10px);
}

:where(body.pagina-prova-campeira) .campeira-cabecalho{
  margin-bottom: 30px;
}

:where(body.pagina-prova-campeira) .campeira-estudo{
  display: grid;
  grid-template-columns: 310px minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}

:where(body.pagina-prova-campeira) .campeira-abas{
  position: sticky;
  top: 112px;
  display: grid;
  gap: 10px;
  padding: 15px;
  border: 3px double #886137;
  border-radius: 7px;
  background:
