  box-shadow: 10px 13px 0 rgba(62, 40, 23, .14);
}

:where(body.pagina-prova-campeira) .campeira-topico{
  width: 100%;
  display: grid;
  grid-template-columns: 43px 1fr;
  gap: 12px;
  align-items: center;
  padding: 13px;
  border: 1px solid rgba(211, 174, 94, .38);
  border-radius: 5px;
  color: #f2dfb6;
  background: rgba(255, 255, 255, .035);
  text-align: left;
  transition:
    transform .2s ease,
    color .2s ease,
    background .2s ease,
    border-color .2s ease;
}

:where(body.pagina-prova-campeira) .campeira-topico:hover,
:where(body.pagina-prova-campeira) .campeira-topico:focus-visible{
  transform: translateX(4px);
  border-color: #d0a451;
  background: rgba(228, 197, 128, .1);
}

:where(body.pagina-prova-campeira) .campeira-topico.ativo{
