}

:where(body.pagina-prova-campeira) .campeira-painel{
  display: none;
  grid-template-columns: minmax(0, 1fr) minmax(340px, .92fr);
  gap: 34px;
  align-items: center;
  min-height: 610px;
  padding: clamp(27px, 4vw, 46px);
  border: 3px double #8c6438;
  border-radius: 8px;
  background:
    linear-gradient(rgba(255, 249, 232, .97), rgba(255, 249, 232, .97)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(74,47,24,.045) 9px 10px);
  box-shadow:
    12px 15px 0 rgba(65, 42, 24, .13),
    inset 0 0 0 5px rgba(124, 82, 42, .045);
}

:where(body.pagina-prova-campeira) .campeira-painel.ativo{
  display: grid;
  animation: campeiraEntrada .36s ease;
}

@keyframes campeiraEntrada {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

:where(body.pagina-prova-campeira) .campeira-painel h2{
